<?php require_once __DIR__.'/../config/config.php';admin_required();$stats=[];foreach(['orders'=>'Total Orders','products'=>'Products','customers'=>'Customers'] as $t=>$label)$stats[$label]=(int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();$revenue=(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='Delivered'")->fetchColumn();require 'layout.php';?><h1>Dashboard</h1><div class="row g-3"><?php foreach($stats as $k=>$v):?><div class="col-md-3"><div class="admin-card"><small><?=$k?></small><h2><?=$v?></h2></div></div><?php endforeach;?><div class="col-md-3"><div class="admin-card"><small>Delivered Revenue</small><h2><?=money($revenue)?></h2></div></div></div><div class="admin-card mt-4"><h4>Quick actions</h4><a href="products.php">Manage products</a> · <a href="orders.php">Manage orders</a> · <a href="export.php">Excel reports</a></div><?php require 'end.php';?>